// Общие шаги экрана /catalog/import (ייבוא מוצרים מאקסל) для #dc1afa и #6ac0be.
import { Page, Request, expect } from '@playwright/test';

export const WARN = 'ספרת הביקורת של הברקוד שגויה — בדקו את הספרות';
/** Поле без колонки (#6ac0be): подсказка, что колонку можно привязать кнопкой ниже. */
export const NO_COL = 'לא זוהתה עמודה · אפשר לשייך עמודה מהרשימה למטה';
/** Пояснение у списка нераспознанных колонок (#6ac0be), вместо прежнего «פתחו «שינוי עמודות» ובחרו לה שדה». */
export const HINT = /לחצו עליה ובחרו איזה נתון היא/;

/** Контрольная цифра EAN/UPC (вес 3/1 справа). */
export function checkDigit(body: string) {
  let n = 0;
  for (let i = body.length - 1, w = 3; i >= 0; i--, w = 4 - w) n += Number(body[i]) * w;
  return (10 - (n % 10)) % 10;
}
export const good = (body: string) => body + checkDigit(body);
export const bad = (body: string) => body + ((checkDigit(body) + 1) % 10);

/** Уникальные коды от метки времени прогона (префикс 2x — внутренний диапазон, не настоящие товары). */
export function codes() {
  const ts = Date.now().toString().slice(-7);
  const r = String(Math.floor(Math.random() * 900 + 100));
  const b13 = `29${ts}${r}`;          // 12 цифр → EAN-13
  const b12 = `28${ts}${r}`;          // второй EAN-13
  const b8 = `2${ts.slice(-4)}${r.slice(0, 2)}`; // 7 цифр → EAN-8
  const b11 = `4${ts}${r}`;           // 11 цифр → UPC-A
  const mid = (() => { const c = b12.split(''); c[6] = String((Number(c[6]) + 1) % 10); return c.join('') + checkDigit(b12); })();
  return {
    ts,
    E13: good(b13), E13bad: bad(b13),
    E13b: good(b12), E13mid: mid,
    E8: good(b8), E8bad: bad(b8),
    UPC: good(b11), UPCbad: bad(b11),
    D14: good(b13) + '1',
  };
}

/** Открыть /catalog/import и дождаться списка מק"ט каталога (иначе дубль «קיים בקטלוג» не успевает определиться). */
export async function openImport(page: Page) {
  await Promise.all([
    page.waitForResponse((r) => r.url().includes('/rest/v1/products?select=sku'), { timeout: 30_000 }),
    page.goto('/catalog/import'),
  ]);
  await expect(page.getByRole('heading', { level: 1, name: 'ייבוא מוצרים מאקסל' })).toBeVisible();
}

export async function upload(page: Page, csv: string, name = 'qa-auto-import.csv') {
  await page.locator('input[type=file]').first().setInputFiles({ name, mimeType: 'text/csv', buffer: Buffer.from(csv, 'utf8') });
}

export const importBtn = (page: Page) => page.locator('main').getByRole('button', { name: /^ייבוא (\d+ מוצרים|מוצר אחד)$/ }).first();
export const counter = (page: Page, n: number) => page.getByRole('button', { name: `ספרת ביקורת שגויה: ${n} — מעבר לשורה`, exact: true });
export const anyCounter = (page: Page) => page.getByRole('button', { name: /^ספרת ביקורת שגויה: \d+/ });
export const skuCell = (page: Page, row: number) => page.getByRole('textbox', { name: `מק"ט, שורה ${row}`, exact: true });
export const nameCell = (page: Page, row: number) => page.getByRole('textbox', { name: `שם מוצר, שורה ${row}`, exact: true });
export const priceCell = (page: Page, row: number) => page.getByRole('textbox', { name: `מחיר, שורה ${row}`, exact: true });
export const warnings = (page: Page) => page.locator('main').getByText(WARN, { exact: true });

/** Кнопка нераспознанной колонки (#6ac0be). */
export const chip = (page: Page, col: string) => page.getByRole('button', { name: `שיוך העמודה «${col}» לנתון`, exact: true });
/** Строка поля в панели «התאמת עמודות». */
export const fieldRow = (page: Page, field: string) => page.getByRole('listitem').filter({ has: page.getByText(field, { exact: true }) }).first();
/** Текст «מהעמודה «X»» (в приложении имя колонки обёрнуто в невидимые символы направления U+2068/U+2069). */
export const fromCol = (col: string) => new RegExp(`מהעמודה «\\u2068?${col.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\u2069?»`);

/** Запросы записи товаров (POST/PATCH к products и «пишущие» rpc импорта). */
export function watchProductWrites(page: Page) {
  const list: string[] = [];
  const isWrite = (r: Request) => !['GET', 'HEAD', 'OPTIONS'].includes(r.method()) &&
    (/\/rest\/v1\/products\b/.test(r.url()) || /\/rest\/v1\/rpc\/[^?]*(import|create_product|insert|upsert)/.test(r.url()));
  page.on('request', (r) => { if (isWrite(r)) list.push(`${r.method()} ${r.url().split('?')[0].replace(/^.*\/rest\/v1\//, '')}`); });
  return list;
}

/** Перехват POST products: запись НЕ уходит в базу (ответ 201 []), тело запроса сохраняется для проверки. */
export async function fakeProductInsert(page: Page) {
  const bodies: Array<Record<string, unknown>[]> = [];
  await page.route('**/rest/v1/products*', (route) => {
    const req = route.request();
    if (req.method() !== 'POST') return route.fallback();
    const data = JSON.parse(req.postData() || '[]');
    bodies.push(Array.isArray(data) ? data : [data]);
    return route.fulfill({ status: 201, contentType: 'application/json', body: '[]' });
  });
  return bodies;
}
